	// WenYan (文言) data
	wenYanStore = map[string][]WenYanEntry{
		"乾乾": {
			{Title: "元者善之长也", Text: "元者，善之长也；亨者，嘉之会也；利者，义之和也；贞者，事之干也。君子体仁足以长人，嘉会足以合礼，利物足以和义，贞固足以干事。君子行此四德者，故曰乾元亨利贞。"},
			{Title: "初九曰潜龙勿用", Text: "初九曰潜龙勿用，何谓也？子曰：龙德而隐者也。不易乎世，不成乎名，遁世无闷，不见是而无闷，乐则行之，忧则违之，确乎其不可拔，潜龙也。"},
			{Title: "九二曰见龙在田利见大人", Text: "九二曰见龙在田利见大人，何谓也？子曰：龙德而正中者也。庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。易曰见龙在田利见大人，君德也。"},
			{Title: "九三曰君子终日乾乾夕惕若厉无咎", Text: "九三曰君子终日乾乾夕惕若厉无咎，何谓也？子曰：君子进德修业。忠信所以进德也，修辞立其诚所以居业也。知至至之，可与几也；知终终之，可与存义也。是故居上位而不骄，在下位而不忧，故乾乾因其时而惕，虽危无咎矣。"},
			{Title: "九四曰或跃在渊无咎", Text: "九四曰或跃在渊无咎，何谓也？子曰：上下无常，非为邪也；进退无恒，非离群也。君子进德修业，欲及时也，故无咎。"},
			{Title: "九五曰飞龙在天利见大人", Text: "九五曰飞龙在天利见大人，何谓也？子曰：同声相应，同气相求。水流湿，火就燥，云从龙，风从虎，圣人作而万物睹，本乎天者亲上，本乎地者亲下，则各从其类也。"},
			{Title: "上九曰亢龙有悔", Text: "上九曰亢龙有悔，何谓也？子曰：贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。"},
			{Title: "潜龙勿用下也", Text: "潜龙勿用，下也。见龙在田，时舍也。终日乾乾，行事也。或跃在渊，自试也。飞龙在天，上治也。亢龙有悔，穷之灾也。乾元用九，天下治也。"},
			{Title: "潜龙勿用阳气潜藏", Text: "潜龙勿用，阳气潜藏。见龙在田，天下文明。终日乾乾，与时偕行。或跃在渊，乾道乃革。飞龙在天，乃位乎天德。亢龙有悔，与时偕极。乾元用九，乃见天则。"},
			{Title: "乾元者始而亨者也", Text: "乾元者，始而亨者也。利贞者，性情也。乾始能以美利利天下，不言所利，大矣哉！大哉乾乎，刚健中正，纯粹精也。六爻发挥，旁通情也。时乘六龙，以御天也。云行雨施，天下平也。"},
		},
		"坤坤": {
			{Title: "坤至柔而动也刚", Text: "坤至柔而动也刚，至静而德方，后得主而有常，含万物而化光。坤道其顺乎，承天而时行。"},
			{Title: "积善之家必有余庆", Text: "积善之家，必有余庆；积不善之家，必有余殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辩之不早辩也。易曰履霜坚冰至，盖言顺也。"},
			{Title: "直其正也方其义也", Text: "直其正也，方其义也。君子敬以直内，义以方外，敬义立而德不孤。直方大，不习无不利，则不疑其所行也。"},
			{Title: "阴虽有美含之", Text: "阴虽有美含之，以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成而代有终也。"},
			{Title: "天地变化草木蕃", Text: "天地变化，草木蕃。天地闭，贤人隐。易曰括囊无咎无誉，盖言谨也。"},
			{Title: "君子黄中通理", Text: "君子黄中通理，正位居体，美在其中而畅于四支，发于事业，美之至也。"},
			{Title: "阴疑于阳必战", Text: "阴疑于阳必战，为其嫌于无阳也，故称龙焉。犹未离其类也，故称血焉。夫玄黄者，天地之杂也，天玄而地黄。"},
		},
	}

